import { PNG } from 'pngjs';
import { PDFDocument } from 'pdf-lib';
import { VideoStream, VideoBufferType } from '@livekit/rtc-node';

/**
 * Keep the latest decoded RGBA frame from a remote video track.
 * @param {import('@livekit/rtc-node').Track} track
 * @returns {{ getLatest: () => { rgba: Uint8Array, width: number, height: number } | null, close: () => Promise<void> }}
 */
export function followVideoTrack(track) {
  const stream = new VideoStream(track);
  /** @type {{ rgba: Uint8Array, width: number, height: number } | null} */
  let latest = null;
  let closed = false;

  const reader = (async () => {
    for await (const event of stream) {
      if (closed) break;
      const frame = event.frame;
      if (!frame?.width || !frame?.height) continue;
      try {
        const converted =
          frame.type === VideoBufferType.RGBA ? frame : frame.convert(VideoBufferType.RGBA);
        latest = {
          rgba: new Uint8Array(converted.data),
          width: converted.width,
          height: converted.height,
        };
      } catch (error) {
        console.warn('[capture] frame convert failed', error);
      }
    }
  })();

  return {
    getLatest: () => latest,
    close: async () => {
      closed = true;
      stream.cancel?.();
      await reader.catch(() => {});
    },
  };
}

/** Crude non-black / variance score so we prefer real document frames. */
export function frameScore(rgba) {
  if (!rgba?.length) return 0;
  let sum = 0;
  let sumSq = 0;
  let n = 0;
  // Sample every 32nd pixel for speed.
  for (let i = 0; i + 2 < rgba.length; i += 32 * 4) {
    const y = 0.299 * rgba[i] + 0.587 * rgba[i + 1] + 0.114 * rgba[i + 2];
    sum += y;
    sumSq += y * y;
    n += 1;
  }
  if (!n) return 0;
  const mean = sum / n;
  const variance = Math.max(0, sumSq / n - mean * mean);
  // Penalize near-black frames.
  return variance * (0.25 + mean / 255);
}

/**
 * @param {Array<{ rgba: Uint8Array, width: number, height: number }>} frames
 * @returns {Promise<Uint8Array>}
 */
export async function framesToPdf(frames) {
  if (!frames.length) throw new Error('No frames to encode');
  const pdf = await PDFDocument.create();
  for (const frame of frames) {
    const png = rgbaToPng(frame.rgba, frame.width, frame.height);
    const embedded = await pdf.embedPng(png);
    const page = pdf.addPage([embedded.width, embedded.height]);
    page.drawImage(embedded, {
      x: 0,
      y: 0,
      width: embedded.width,
      height: embedded.height,
    });
  }
  return pdf.save();
}

function rgbaToPng(rgba, width, height) {
  const png = new PNG({ width, height });
  png.data = Buffer.from(rgba);
  return PNG.sync.write(png);
}

/**
 * Collect up to `count` strong frames over `durationMs`.
 * @param {() => ({ rgba: Uint8Array, width: number, height: number } | null)} getLatest
 * @param {{ durationMs?: number, count?: number, minScore?: number }} [options]
 */
export async function collectBestFrames(getLatest, options = {}) {
  const durationMs = options.durationMs ?? 8_000;
  const count = options.count ?? 2;
  const minScore = options.minScore ?? 80;
  const started = Date.now();
  /** @type {Array<{ frame: { rgba: Uint8Array, width: number, height: number }, score: number }>} */
  const best = [];

  while (Date.now() - started < durationMs) {
    const frame = getLatest();
    if (frame) {
      const score = frameScore(frame.rgba);
      if (score >= minScore) {
        best.push({ frame, score });
        best.sort((a, b) => b.score - a.score);
        if (best.length > count * 3) best.length = count * 3;
      }
    }
    await new Promise(r => setTimeout(r, 350));
  }

  const picked = [];
  for (const item of best) {
    if (picked.length >= count) break;
    // Deduplicate near-identical scores/time by keeping spaced picks.
    if (picked.some(p => Math.abs(p.score - item.score) < 1)) continue;
    picked.push(item);
  }
  if (!picked.length && best[0]) picked.push(best[0]);
  return picked.map(p => p.frame);
}

/**
 * Upload a captured PDF into Unburden's document API.
 * @param {Uint8Array} pdfBytes
 * @param {{
 *   apiBase?: string,
 *   patientId?: string,
 *   sessionId?: string | null,
 *   sourceLabel?: string,
 * }} [options]
 */
export async function uploadCapturedPdf(pdfBytes, options = {}) {
  const apiBase = (options.apiBase || process.env.UNBURDEN_API_BASE || 'http://localhost:8000').replace(/\/$/, '');
  const patientId = options.patientId || process.env.UNBURDEN_PATIENT_ID || 'patient-raymond-yao';
  const sourceLabel =
    options.sourceLabel ||
    `FaceTime capture — ${new Date().toISOString().replace('T', ' ').slice(0, 19)}`;

  const form = new FormData();
  form.append(
    'file',
    new Blob([pdfBytes], { type: 'application/pdf' }),
    'facetime-capture.pdf',
  );
  form.append('source_label', sourceLabel);
  form.append('document_type', 'clinical_note');

  const response = await fetch(`${apiBase}/api/patients/${patientId}/documents`, {
    method: 'POST',
    body: form,
  });
  if (!response.ok) {
    const detail = await response.text();
    throw new Error(`Unburden upload failed (${response.status}): ${detail}`);
  }
  const document = await response.json();

  if (options.sessionId) {
    try {
      await fetch(`${apiBase}/api/patients/${patientId}/chert/sessions/${options.sessionId}/uploaded`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          document_id: document.id,
          source_label: document.source_label || sourceLabel,
        }),
      });
    } catch (error) {
      console.warn('[upload] session callback failed', error);
    }
  }

  return document;
}

export function patientIdFromMetadata(raw) {
  try {
    const parsed = JSON.parse(raw || '{}');
    if (typeof parsed.patient_id === 'string' && parsed.patient_id) return parsed.patient_id;
    if (typeof parsed.unburden_patient_id === 'string' && parsed.unburden_patient_id) {
      return parsed.unburden_patient_id;
    }
  } catch {
    /* ignore */
  }
  return process.env.UNBURDEN_PATIENT_ID || 'patient-raymond-yao';
}

export function sessionIdFromMetadata(raw) {
  try {
    const parsed = JSON.parse(raw || '{}');
    if (typeof parsed.session_id === 'string' && parsed.session_id) return parsed.session_id;
    if (typeof parsed.unburden_session_id === 'string' && parsed.unburden_session_id) {
      return parsed.unburden_session_id;
    }
  } catch {
    /* ignore */
  }
  return null;
}

import { fileURLToPath } from 'node:url';
import { AutoSubscribe, defineAgent, llm, voice } from '@livekit/agents';
import { realtime } from '@livekit/agents-plugin-openai';
import {
  LocalVideoTrack,
  RoomEvent,
  TrackKind,
  TrackSource,
  VideoBufferType,
  VideoFrame,
  VideoSource,
} from '@livekit/rtc-node';
import { collectBestFrames, followVideoTrack, framesToPdf } from './capture.mjs';
import { runAgent } from './chert-rooms.mjs';
import { drawFace, FPS, HEIGHT, WIDTH } from './face.mjs';
import { greetOnBridgeReady } from './greet.mjs';
import {
  patientIdFromMetadata,
  sessionIdFromMetadata,
  uploadCapturedPdf,
} from './upload.mjs';

const instructions = `You are Unburden's FaceTime document assistant on a video call.
Your only job is to help the patient get a paper or screen document into their chart.
Speak in short, clear sentences.
As soon as the call is ready, ask them to hold the document steady so it fills the camera.
When the document looks readable on camera, call the capture_document tool.
After a successful capture, tell them it was uploaded and they can hang up.
If capture fails, ask them to adjust lighting/angle and try once more.
You are an AI assistant, not a clinician.`;

const greeting =
  'Greet the caller in one short sentence: say you are Unburden’s document assistant and ask them to hold their document up to the camera, filling the frame.';

const openaiKeyReady = () => {
  const key = process.env.OPENAI_API_KEY || '';
  return Boolean(key) && !key.includes('YOUR_');
};

const agent = defineAgent({
  entry: async ctx => {
    // Need caller video frames for document capture.
    await ctx.connect(undefined, AutoSubscribe.SUBSCRIBE_ALL);
    const caller = await ctx.waitForParticipant();

    const jobMetadata = ctx.job?.metadata || '{}';
    const patientId = patientIdFromMetadata(jobMetadata);
    const sessionId = sessionIdFromMetadata(jobMetadata);
    console.log(`[document-intake] patient=${patientId} session=${sessionId || 'none'}`);

    const source = new VideoSource(WIDTH, HEIGHT);
    const track = LocalVideoTrack.createVideoTrack('agent-video', source);
    let tick = 0;
    let speaking = false;
    const paint = () =>
      source.captureFrame(
        new VideoFrame(drawFace(tick++, speaking), WIDTH, HEIGHT, VideoBufferType.RGBA),
      );
    paint();
    await ctx.room.localParticipant.publishTrack(track, { source: TrackSource.SOURCE_CAMERA });
    const timer = setInterval(paint, 1000 / FPS);

    /** @type {ReturnType<typeof followVideoTrack> | null} */
    let videoFollow = null;
    let uploaded = false;

    const attachVideo = remoteTrack => {
      if (!remoteTrack || remoteTrack.kind !== TrackKind.KIND_VIDEO) return;
      if (videoFollow) void videoFollow.close();
      videoFollow = followVideoTrack(remoteTrack);
      console.log('[document-intake] following remote video track');
    };

    for (const participant of ctx.room.remoteParticipants.values()) {
      for (const publication of participant.trackPublications.values()) {
        if (publication.track) attachVideo(publication.track);
      }
    }
    ctx.room.on(RoomEvent.TrackSubscribed, (remoteTrack, _pub, participant) => {
      console.log(`[document-intake] track subscribed kind=${remoteTrack.kind} from=${participant.identity}`);
      attachVideo(remoteTrack);
    });

    const captureAndUpload = async () => {
      if (uploaded) return { ok: true, message: 'Already uploaded a document on this call.' };
      if (!videoFollow) {
        return {
          ok: false,
          message: 'Caller video is not available yet. Ask them to enable FaceTime Video / camera.',
        };
      }
      console.log('[document-intake] capturing frames…');
      const frames = await collectBestFrames(() => videoFollow.getLatest(), {
        durationMs: 7_000,
        count: 2,
        minScore: 40,
      });
      if (!frames.length) {
        return {
          ok: false,
          message: 'Could not get a clear frame. Ask the caller to hold the document closer and steadier.',
        };
      }
      const pdfBytes = await framesToPdf(frames);
      const document = await uploadCapturedPdf(pdfBytes, { patientId, sessionId });
      uploaded = true;
      console.log(`[document-intake] uploaded document ${document.id}`);
      return {
        ok: true,
        message: `Uploaded as “${document.source_label || document.original_filename}”.`,
        document_id: document.id,
        source_label: document.source_label,
      };
    };

    if (!openaiKeyReady()) {
      console.warn(
        '[document-intake] OPENAI_API_KEY missing — running capture-only mode after bridge_ready (no conversational voice).',
      );
      const stopGreeting = greetOnBridgeReady(ctx.room, () => {
        console.log('[document-intake] bridge ready — starting timed capture');
        void (async () => {
          // Give the caller a few seconds to present the document.
          await new Promise(r => setTimeout(r, 4_000));
          const result = await captureAndUpload();
          console.log('[document-intake] capture result', result);
          await new Promise(r => setTimeout(r, 2_000));
          ctx.shutdown(result.ok ? 'uploaded' : 'capture-failed');
        })();
      });
      ctx.addShutdownCallback(async () => {
        stopGreeting();
        clearInterval(timer);
        if (videoFollow) await videoFollow.close();
        await track.close();
        await source.close();
      });
      return;
    }

    const session = new voice.AgentSession({
      llm: new realtime.RealtimeModel({ model: 'gpt-realtime', voice: 'marin' }),
    });
    session.on(voice.AgentSessionEventTypes.AgentStateChanged, event => {
      speaking = event.newState === 'speaking';
    });

    const captureTool = llm.tool({
      description:
        'Capture the document currently visible on the caller’s FaceTime camera and upload it to the Unburden patient chart as a PDF.',
      parameters: llm.openaiSchema({
        type: 'object',
        properties: {},
        required: [],
      }),
      execute: async () => {
        const result = await captureAndUpload();
        return JSON.stringify(result);
      },
    });

    ctx.addShutdownCallback(async () => {
      clearInterval(timer);
      if (videoFollow) await videoFollow.close();
      await session.close();
      await track.close();
      await source.close();
    });

    await session.start({
      room: ctx.room,
      agent: new voice.Agent({
        instructions,
        tools: { capture_document: captureTool },
      }),
      record: false,
      inputOptions: {
        participantIdentity: caller.identity,
        audioEnabled: true,
        // Feed the latest frame into the realtime model when available.
        videoEnabled: true,
        textEnabled: false,
        closeOnDisconnect: true,
        deleteRoomOnClose: false,
      },
      outputOptions: { audioEnabled: true, transcriptionEnabled: false },
    });

    const stopGreeting = greetOnBridgeReady(ctx.room, () =>
      session.generateReply({ instructions: greeting }),
    );
    ctx.addShutdownCallback(async () => stopGreeting());

    // Safety net: if the model never calls the tool, capture once after a delay.
    const stopAuto = greetOnBridgeReady(ctx.room, () => {
      void (async () => {
        await new Promise(r => setTimeout(r, 22_000));
        if (!uploaded) {
          console.log('[document-intake] auto-capture fallback');
          const result = await captureAndUpload();
          if (result.ok) {
            session.generateReply({
              instructions:
                'Tell the caller you captured and uploaded their document, and they can hang up now.',
            });
          }
        }
      })();
    });
    ctx.addShutdownCallback(async () => stopAuto());
  },
});

export default agent;

runAgent(agent, {
  file: fileURLToPath(import.meta.url),
  agentName: process.env.AGENT_NAME || 'document-intake',
});

