import type {
  CandidateStatus,
  DocumentDetail,
  DocumentSummary,
  EvidenceCandidate,
  EvidencePacket,
  Patient,
  PolicyEvaluation,
  PolicySummary,
} from "./types";

export async function reseedDemo() {
  return request<{
    patient_id: string;
    documents_created: number;
