def _pick_agent_identity(participants: list[ParticipantInfo]) -> str | None:
    """LiveKit Agents join as agent-* identities, not the dispatch name."""
    if not participants:
        return None
    for participant in participants:
        kind = int(getattr(participant, "kind", 0) or 0)
        identity = participant.identity or ""
        # ParticipantInfo.Kind.AGENT == 4 in livekit protocol
        if kind == 4 or identity.startswith("agent-"):
            return identity
    # Fallback: first publisher that isn't a Chert bridge placeholder.
    for participant in participants:
        identity = participant.identity or ""
        if identity and not identity.startswith("chert-bridge-"):
            return identity
    return participants[0].identity or None


async def _wait_for_agent_identity(
    lk: LiveKitAPI, room_name: str, *, timeout_s: float = 20.0
) -> str:
    deadline = asyncio.get_event_loop().time() + timeout_s
    last_ids: list[str] = []
    while asyncio.get_event_loop().time() < deadline:
        listed = await lk.room.list_participants(ListParticipantsRequest(room=room_name))
        participants = list(listed.participants or [])
        last_ids = [p.identity for p in participants if p.identity]
        identity = _pick_agent_identity(participants)
        if identity:
            return identity
        await asyncio.sleep(0.5)
    raise RuntimeError(
        "Timed out waiting for the document-intake agent to join the LiveKit room. "
        f"Seen participants: {last_ids or 'none'}. Is `npm start` running in agents/document-intake?"
    )

