"use client";

import { useEffect, useRef, useState } from "react";
import { getChertSession, ringDocumentAssistant } from "@/lib/api";
import { DEFAULT_PATIENT_ID } from "@/lib/constants";
import type {
  CandidateStatus,
  ChertSession,
  EvidenceCandidate,
  PolicyEvaluation,
  RequirementEvaluation,
} from "@/lib/types";

export type RequirementStatusChange = {
  requirement_id: string;
  title: string;
  from: string;
  to: string;
};

type RingPhase =
  | "idle"
  | "preparing"
  | "ringing"
  | "active"
  | "uploaded"
  | "failed";

function phaseFromSession(session: ChertSession): RingPhase {
  const status = session.status.toLowerCase();
  if (session.document_id || status === "uploaded") return "uploaded";
  if (status === "failed" || status === "ended") return "failed";
  if (
    status === "active" ||
    status === "answered" ||
    status === "bridge_ready" ||
    status === "in_call"
  ) {
    return "active";
  }
  if (
    status === "ringing" ||
    status === "queued" ||
    status === "dialing" ||
    status === "allocated"
  ) {
    return "ringing";
  }
  if (status === "preparing") return "preparing";
  return "ringing";
}

function ringStatusLabel(phase: RingPhase): string {
  switch (phase) {
    case "preparing":
      return "Preparing FaceTime…";
    case "ringing":
      return "Ringing patient…";
    case "active":
      return "On the call…";
    case "uploaded":
      return "Document uploaded";
    case "failed":
      return "Request failed";
    default:
      return "";
  }
}

type RequirementsChecklistProps = {
  evaluation: PolicyEvaluation | null;
  loading?: boolean;
  statusChanges?: RequirementStatusChange[];
  patientId?: string;
